/*
 * Digitexa UI — design tokens
 *
 * Layers:
 *   1. Semantic tokens  → what components use (--bg, --fg, --accent ...)  [this file]
 *   2. Tailwind mapping → @theme inline in theme.css
 *
 * Light lives in :root; dark is defined separately (not inverted).
 * Accent: <html data-accent="ember|cobalt|moss|plum|rose|graphite">
 * Theme:  <html data-theme="light|dark">  (falls back to the system preference)
 */

:root {
  /* ---- typography: dense desktop scale ---- */
  --font-size-2xs: 10.5px;
  --font-size-xs: 11.5px;
  --font-size-sm: 12.5px;
  --font-size-base: 13px;
  --font-size-md: 14px;
  --font-size-lg: 16px;
  --font-size-xl: 19px;
  --font-size-2xl: 24px;

  /* ---- control heights ---- */
  --control-sm: 24px;
  --control-md: 30px;
  --control-lg: 36px;

  /* ---- radius ---- */
  --radius: 6px;
  --radius-small: 4px;
  --radius-large: 9px;
  --radius-full: 999px;

  /* ---- motion ---- */
  --motion-ease: cubic-bezier(0.22, 0.9, 0.3, 1);
  --motion-fast: 110ms;
  --motion: 170ms;
}

/* =========================================================
 * LIGHT — warm neutrals (hue ≈ 75, low chroma)
 * ========================================================= */
:root {
  color-scheme: light;

  --bg: oklch(0.985 0.004 80);
  --bg-subtle: oklch(0.968 0.006 78);
  --surface: oklch(1 0 0);
  --surface-raised: oklch(1 0 0);
  --muted: oklch(0.948 0.008 76);
  --muted-hover: oklch(0.925 0.01 75);

  --fg: oklch(0.235 0.012 65);
  --fg-muted: oklch(0.47 0.014 68);
  --fg-subtle: oklch(0.62 0.012 70);
  --fg-disabled: oklch(0.74 0.008 72);

  --border: oklch(0.905 0.009 75);
  --border-strong: oklch(0.84 0.012 74);
  --input: oklch(0.875 0.011 75);

  --overlay: oklch(0.2 0.01 60 / 0.38);
  --shadow-color: 40 30% 20%;
  --elevation-1: 0 1px 2px hsl(var(--shadow-color) / 0.07);
  --elevation-2: 0 2px 6px hsl(var(--shadow-color) / 0.07), 0 1px 2px hsl(var(--shadow-color) / 0.05);
  --elevation-3: 0 12px 32px -6px hsl(var(--shadow-color) / 0.18), 0 2px 6px hsl(var(--shadow-color) / 0.06);

  /* semantic */
  --success: oklch(0.56 0.12 152);
  --success-subtle: oklch(0.95 0.035 152);
  --warning: oklch(0.66 0.14 72);
  --warning-subtle: oklch(0.96 0.045 85);
  --danger: oklch(0.56 0.18 27);
  --danger-subtle: oklch(0.955 0.03 25);
  --danger-fg: oklch(0.99 0.005 25);
  --info: oklch(0.56 0.12 245);
  --info-subtle: oklch(0.955 0.025 245);

  /* work statuses */
  --status-backlog: oklch(0.63 0.01 70);
  --status-backlog-subtle: oklch(0.945 0.006 72);
  --status-todo: oklch(0.55 0.13 250);
  --status-todo-subtle: oklch(0.95 0.025 250);
  --status-progress: oklch(0.67 0.15 62);
  --status-progress-subtle: oklch(0.955 0.045 72);
  --status-review: oklch(0.55 0.16 300);
  --status-review-subtle: oklch(0.95 0.03 300);
  --status-done: oklch(0.57 0.12 155);
  --status-done-subtle: oklch(0.95 0.035 155);
}

/* =========================================================
 * DARK — defined on its own, warm dark surfaces
 * ========================================================= */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;

    --bg: oklch(0.175 0.006 60);
    --bg-subtle: oklch(0.155 0.006 60);
    --surface: oklch(0.205 0.007 62);
    --surface-raised: oklch(0.235 0.008 62);
    --muted: oklch(0.255 0.008 64);
    --muted-hover: oklch(0.29 0.009 64);

    --fg: oklch(0.935 0.006 80);
    --fg-muted: oklch(0.72 0.01 75);
    --fg-subtle: oklch(0.57 0.01 72);
    --fg-disabled: oklch(0.43 0.008 70);

    --border: oklch(0.285 0.008 64);
    --border-strong: oklch(0.36 0.01 66);
    --input: oklch(0.33 0.01 66);

    --overlay: oklch(0.08 0.005 60 / 0.6);
    --shadow-color: 30 30% 2%;
    --elevation-1: 0 1px 2px hsl(var(--shadow-color) / 0.4);
    --elevation-2: 0 2px 8px hsl(var(--shadow-color) / 0.45);
    --elevation-3: 0 16px 40px -8px hsl(var(--shadow-color) / 0.7), 0 0 0 1px oklch(1 0 0 / 0.04);

    --success: oklch(0.72 0.13 152);
    --success-subtle: oklch(0.29 0.045 152);
    --warning: oklch(0.79 0.13 78);
    --warning-subtle: oklch(0.3 0.05 75);
    --danger: oklch(0.68 0.17 25);
    --danger-subtle: oklch(0.29 0.06 25);
    --danger-fg: oklch(0.99 0.005 25);
    --info: oklch(0.72 0.12 245);
    --info-subtle: oklch(0.29 0.045 245);

    --status-backlog: oklch(0.6 0.01 70);
    --status-backlog-subtle: oklch(0.27 0.006 68);
    --status-todo: oklch(0.72 0.12 250);
    --status-todo-subtle: oklch(0.29 0.05 250);
    --status-progress: oklch(0.79 0.14 70);
    --status-progress-subtle: oklch(0.31 0.055 70);
    --status-review: oklch(0.72 0.14 300);
    --status-review-subtle: oklch(0.29 0.055 300);
    --status-done: oklch(0.73 0.13 155);
    --status-done-subtle: oklch(0.29 0.05 155);
  }
}

:root[data-theme="dark"] {
  color-scheme: dark;

  --bg: oklch(0.175 0.006 60);
  --bg-subtle: oklch(0.155 0.006 60);
  --surface: oklch(0.205 0.007 62);
  --surface-raised: oklch(0.235 0.008 62);
  --muted: oklch(0.255 0.008 64);
  --muted-hover: oklch(0.29 0.009 64);

  --fg: oklch(0.935 0.006 80);
  --fg-muted: oklch(0.72 0.01 75);
  --fg-subtle: oklch(0.57 0.01 72);
  --fg-disabled: oklch(0.43 0.008 70);

  --border: oklch(0.285 0.008 64);
  --border-strong: oklch(0.36 0.01 66);
  --input: oklch(0.33 0.01 66);

  --overlay: oklch(0.08 0.005 60 / 0.6);
  --shadow-color: 30 30% 2%;
  --elevation-1: 0 1px 2px hsl(var(--shadow-color) / 0.4);
  --elevation-2: 0 2px 8px hsl(var(--shadow-color) / 0.45);
  --elevation-3: 0 16px 40px -8px hsl(var(--shadow-color) / 0.7), 0 0 0 1px oklch(1 0 0 / 0.04);

  --success: oklch(0.72 0.13 152);
  --success-subtle: oklch(0.29 0.045 152);
  --warning: oklch(0.79 0.13 78);
  --warning-subtle: oklch(0.3 0.05 75);
  --danger: oklch(0.68 0.17 25);
  --danger-subtle: oklch(0.29 0.06 25);
  --danger-fg: oklch(0.99 0.005 25);
  --info: oklch(0.72 0.12 245);
  --info-subtle: oklch(0.29 0.045 245);

  --status-backlog: oklch(0.6 0.01 70);
  --status-backlog-subtle: oklch(0.27 0.006 68);
  --status-todo: oklch(0.72 0.12 250);
  --status-todo-subtle: oklch(0.29 0.05 250);
  --status-progress: oklch(0.79 0.14 70);
  --status-progress-subtle: oklch(0.31 0.055 70);
  --status-review: oklch(0.72 0.14 300);
  --status-review-subtle: oklch(0.29 0.055 300);
  --status-done: oklch(0.73 0.13 155);
  --status-done-subtle: oklch(0.29 0.05 155);
}

/* =========================================================
 * ACCENTS — data-accent
 * Each one carries separate light + dark values.
 * ========================================================= */

/* ember (default) — burnt orange */
:root,
:root[data-accent="ember"] {
  --accent: oklch(0.6 0.165 45);
  --accent-hover: oklch(0.55 0.165 44);
  --accent-fg: oklch(0.99 0.008 60);
  --accent-subtle: oklch(0.955 0.03 55);
  --accent-subtle-fg: oklch(0.47 0.13 44);
}
:root[data-accent="cobalt"] {
  --accent: oklch(0.54 0.17 258);
  --accent-hover: oklch(0.49 0.17 258);
  --accent-fg: oklch(0.99 0.005 258);
  --accent-subtle: oklch(0.95 0.025 255);
  --accent-subtle-fg: oklch(0.44 0.15 258);
}
:root[data-accent="moss"] {
  --accent: oklch(0.53 0.11 145);
  --accent-hover: oklch(0.48 0.11 145);
  --accent-fg: oklch(0.99 0.01 140);
  --accent-subtle: oklch(0.95 0.03 140);
  --accent-subtle-fg: oklch(0.42 0.09 145);
}
:root[data-accent="plum"] {
  --accent: oklch(0.52 0.16 315);
  --accent-hover: oklch(0.47 0.16 315);
  --accent-fg: oklch(0.99 0.008 315);
  --accent-subtle: oklch(0.95 0.025 315);
  --accent-subtle-fg: oklch(0.43 0.14 315);
}
:root[data-accent="rose"] {
  --accent: oklch(0.58 0.18 12);
  --accent-hover: oklch(0.53 0.18 12);
  --accent-fg: oklch(0.99 0.008 12);
  --accent-subtle: oklch(0.955 0.025 12);
  --accent-subtle-fg: oklch(0.47 0.16 12);
}
:root[data-accent="graphite"] {
  --accent: oklch(0.3 0.012 65);
  --accent-hover: oklch(0.22 0.012 65);
  --accent-fg: oklch(0.98 0.004 80);
  --accent-subtle: oklch(0.94 0.008 75);
  --accent-subtle-fg: oklch(0.3 0.012 65);
}

/* dark accent values: lighter tones that read on dark surfaces */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]),
  :root:not([data-theme="light"])[data-accent="ember"] {
    --accent: oklch(0.7 0.16 50);
    --accent-hover: oklch(0.75 0.15 52);
    --accent-fg: oklch(0.2 0.03 45);
    --accent-subtle: oklch(0.3 0.06 48);
    --accent-subtle-fg: oklch(0.82 0.11 55);
  }
  :root:not([data-theme="light"])[data-accent="cobalt"] {
    --accent: oklch(0.68 0.15 255);
    --accent-hover: oklch(0.73 0.14 255);
    --accent-fg: oklch(0.18 0.04 258);
    --accent-subtle: oklch(0.3 0.07 258);
    --accent-subtle-fg: oklch(0.82 0.09 255);
  }
  :root:not([data-theme="light"])[data-accent="moss"] {
    --accent: oklch(0.7 0.13 145);
    --accent-hover: oklch(0.75 0.12 145);
    --accent-fg: oklch(0.18 0.04 145);
    --accent-subtle: oklch(0.29 0.05 145);
    --accent-subtle-fg: oklch(0.83 0.1 145);
  }
  :root:not([data-theme="light"])[data-accent="plum"] {
    --accent: oklch(0.68 0.15 315);
    --accent-hover: oklch(0.73 0.14 315);
    --accent-fg: oklch(0.18 0.04 315);
    --accent-subtle: oklch(0.29 0.06 315);
    --accent-subtle-fg: oklch(0.83 0.09 315);
  }
  :root:not([data-theme="light"])[data-accent="rose"] {
    --accent: oklch(0.69 0.17 12);
    --accent-hover: oklch(0.74 0.16 12);
    --accent-fg: oklch(0.18 0.04 12);
    --accent-subtle: oklch(0.3 0.07 12);
    --accent-subtle-fg: oklch(0.83 0.1 12);
  }
  :root:not([data-theme="light"])[data-accent="graphite"] {
    --accent: oklch(0.92 0.006 80);
    --accent-hover: oklch(0.98 0.004 80);
    --accent-fg: oklch(0.2 0.01 65);
    --accent-subtle: oklch(0.3 0.008 65);
    --accent-subtle-fg: oklch(0.92 0.006 80);
  }
}

:root[data-theme="dark"],
:root[data-theme="dark"][data-accent="ember"] {
  --accent: oklch(0.7 0.16 50);
  --accent-hover: oklch(0.75 0.15 52);
  --accent-fg: oklch(0.2 0.03 45);
  --accent-subtle: oklch(0.3 0.06 48);
  --accent-subtle-fg: oklch(0.82 0.11 55);
}
:root[data-theme="dark"][data-accent="cobalt"] {
  --accent: oklch(0.68 0.15 255);
  --accent-hover: oklch(0.73 0.14 255);
  --accent-fg: oklch(0.18 0.04 258);
  --accent-subtle: oklch(0.3 0.07 258);
  --accent-subtle-fg: oklch(0.82 0.09 255);
}
:root[data-theme="dark"][data-accent="moss"] {
  --accent: oklch(0.7 0.13 145);
  --accent-hover: oklch(0.75 0.12 145);
  --accent-fg: oklch(0.18 0.04 145);
  --accent-subtle: oklch(0.29 0.05 145);
  --accent-subtle-fg: oklch(0.83 0.1 145);
}
:root[data-theme="dark"][data-accent="plum"] {
  --accent: oklch(0.68 0.15 315);
  --accent-hover: oklch(0.73 0.14 315);
  --accent-fg: oklch(0.18 0.04 315);
  --accent-subtle: oklch(0.29 0.06 315);
  --accent-subtle-fg: oklch(0.83 0.09 315);
}
:root[data-theme="dark"][data-accent="rose"] {
  --accent: oklch(0.69 0.17 12);
  --accent-hover: oklch(0.74 0.16 12);
  --accent-fg: oklch(0.18 0.04 12);
  --accent-subtle: oklch(0.3 0.07 12);
  --accent-subtle-fg: oklch(0.83 0.1 12);
}
:root[data-theme="dark"][data-accent="graphite"] {
  --accent: oklch(0.92 0.006 80);
  --accent-hover: oklch(0.98 0.004 80);
  --accent-fg: oklch(0.2 0.01 65);
  --accent-subtle: oklch(0.3 0.008 65);
  --accent-subtle-fg: oklch(0.92 0.006 80);
}

/* the focus ring always follows the accent */
:root {
  --ring: var(--accent);
}

/*
 * Digitexa UI — Tailwind v4 mapping
 * Binds the variables from tokens.css to utilities (bg-surface, text-fg-muted, bg-status-done ...)
 * and defines the dark: variant from data-theme + the system preference.
 */

@custom-variant dark {
  @media (prefers-color-scheme: dark) {
    &:where(:root:not([data-theme="light"]) *) {
      @slot;
    }
  }
  &:where([data-theme="dark"] *) {
    @slot;
  }
}

/* Map tokens to Tailwind utilities: bg-surface, text-fg-muted, border-border ... */
@theme inline {
  --font-sans: var(--font-geist-sans, ui-sans-serif), system-ui, sans-serif;
  --font-mono: var(--font-geist-mono, ui-monospace), monospace;

  --text-2xs: var(--font-size-2xs);
  --text-2xs--line-height: 14px;
  --text-xs: var(--font-size-xs);
  --text-xs--line-height: 16px;
  --text-sm: var(--font-size-sm);
  --text-sm--line-height: 18px;
  --text-base: var(--font-size-base);
  --text-base--line-height: 19px;
  --text-md: var(--font-size-md);
  --text-md--line-height: 20px;
  --text-lg: var(--font-size-lg);
  --text-lg--line-height: 22px;
  --text-xl: var(--font-size-xl);
  --text-xl--line-height: 26px;
  --text-2xl: var(--font-size-2xl);
  --text-2xl--line-height: 30px;

  --radius-sm: var(--radius-small);
  --radius-md: var(--radius);
  --radius-lg: var(--radius-large);

  --shadow-sm: var(--elevation-1);
  --shadow-md: var(--elevation-2);
  --shadow-lg: var(--elevation-3);

  --color-bg: var(--bg);
  --color-bg-subtle: var(--bg-subtle);
  --color-surface: var(--surface);
  --color-surface-raised: var(--surface-raised);
  --color-muted: var(--muted);
  --color-muted-hover: var(--muted-hover);
  --color-fg: var(--fg);
  --color-fg-muted: var(--fg-muted);
  --color-fg-subtle: var(--fg-subtle);
  --color-fg-disabled: var(--fg-disabled);
  --color-border: var(--border);
  --color-border-strong: var(--border-strong);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-overlay: var(--overlay);

  --color-accent: var(--accent);
  --color-accent-hover: var(--accent-hover);
  --color-accent-fg: var(--accent-fg);
  --color-accent-subtle: var(--accent-subtle);
  --color-accent-subtle-fg: var(--accent-subtle-fg);

  --color-success: var(--success);
  --color-success-subtle: var(--success-subtle);
  --color-warning: var(--warning);
  --color-warning-subtle: var(--warning-subtle);
  --color-danger: var(--danger);
  --color-danger-subtle: var(--danger-subtle);
  --color-danger-fg: var(--danger-fg);
  --color-info: var(--info);
  --color-info-subtle: var(--info-subtle);

  --color-status-backlog: var(--status-backlog);
  --color-status-backlog-subtle: var(--status-backlog-subtle);
  --color-status-todo: var(--status-todo);
  --color-status-todo-subtle: var(--status-todo-subtle);
  --color-status-progress: var(--status-progress);
  --color-status-progress-subtle: var(--status-progress-subtle);
  --color-status-review: var(--status-review);
  --color-status-review-subtle: var(--status-review-subtle);
  --color-status-done: var(--status-done);
  --color-status-done-subtle: var(--status-done-subtle);

  --ease-out: var(--motion-ease);
}

@layer base {
  *,
  ::before,
  ::after {
    border-color: var(--border);
  }
  body {
    background: var(--bg);
    color: var(--fg);
    font-family: var(--font-sans);
    font-size: var(--font-size-base);
    line-height: 19px;
    -webkit-font-smoothing: antialiased;
    font-feature-settings: "cv11", "ss01";
  }
  /* Tailwind v4 gives buttons cursor: default; anything clickable should get a pointer. */
  button,
  [role="button"],
  [role="radio"],
  [role="checkbox"],
  [role="switch"],
  [role="tab"],
  [role="option"],
  [role="menuitem"],
  a[href],
  label[for],
  select,
  summary,
  input[type="checkbox"],
  input[type="radio"],
  input[type="file"],
  input[type="submit"],
  input[type="button"],
  input[type="reset"],
  input[type="range"],
  input[type="color"],
  ::file-selector-button {
    cursor: pointer;
  }
  :disabled,
  [aria-disabled="true"],
  [data-disabled] {
    cursor: not-allowed;
  }
  ::selection {
    background: var(--accent-subtle);
    color: var(--fg);
  }
}

@keyframes dx-fade-in { from { opacity: 0 } to { opacity: 1 } }
@keyframes dx-fade-out { from { opacity: 1 } to { opacity: 0 } }
@keyframes dx-pop-in {
  from { opacity: 0; transform: translate(-50%, -48%) scale(0.97) }
  to { opacity: 1; transform: translate(-50%, -50%) scale(1) }
}
@keyframes dx-pop-out {
  from { opacity: 1; transform: translate(-50%, -50%) scale(1) }
  to { opacity: 0; transform: translate(-50%, -48%) scale(0.97) }
}
